use chrono::{Days, NaiveDate, ParseError};

pub struct Invoice {
    pub id: u32,
    pub issued_on: String,
}

pub fn due_label(invoice: &Invoice) -> Result<String, ParseError> {
    let issued = NaiveDate::parse_from_str(&invoice.issued_on, "%Y-%m-%d")?;
    let due = issued + Days::new(30);
    Ok(due.format("%b %-d, %Y").to_string())
}

use chrono::{DateTime, Days, ParseError, Utc};

pub struct Invoice {
    pub id: u32,
    pub issued_at: String,
}

pub fn due_label(invoice: &Invoice) -> Result<String, ParseError> {
    let issued: DateTime<Utc> =
        DateTime::parse_from_rfc3339(&invoice.issued_at)?.with_timezone(&Utc);
    let due = issued.date_naive() + Days::new(30);
    Ok(due.format("%b %-d, %Y").to_string())
}
